	fmt.Println("    -v                 Show version.")
	fmt.Println("    -all               Display table event for pass and skip. (Failed items always displayed)")
	fmt.Println("    -pass              Display table for passed tests.")
	fmt.Println("    -skip              Display table for skipped tests.")
	fmt.Println("    -notests           Display packages containing no test files or empty test files.")
