	fmt.Println("    -include-timestamp Include timestamps in follow output. ")
	fmt.Println("    -progress          Print a single summary line for each package. Useful for long running test suites.")
	fmt.Println("    -compare           Compare against a previous test output file. (experimental)")
	fmt.Println("    -trimpath          Remove path prefix from package names in output, simplifying their display.")
}

