	fmt.Println("Usage:")
	fmt.Println("    go test ./... -json | tparse [options...]")
	fmt.Println("    go test [packages...] -json | tparse [options...]")
	fmt.Println("    go test [packages...] -json > pkgs.out ; tparse [options...] -file pkgs.out")
	fmt.Println()
	fmt.Println("Options:")
	fmt.Println("    -h                 Show help.")
	fmt.Println("    -v                 Show version.")
	fmt.Println("    -all               Display table event for pass and skip. (Failed items always displayed)")
	fmt.Println("    -pass              Display table for passed tests.")
	fmt.Println("    -skip              Display table for skipped tests.")
	fmt.Println("    -notests           Display packages containing no test files or empty test files.")
	fmt.Println("    -smallscreen       Split subtest names vertically to fit on smaller screens.")
	fmt.Println("    -slow              Number of slowest tests to display. Default is 0, display all.")
	fmt.Println("    -sort              Sort table output by attribute [name, elapsed, cover]. Default is name.")
	fmt.Println("    -nocolor           Disable all colors. (NO_COLOR also supported)")
	fmt.Println("    -format            The output format for tables [basic, plain, markdown]. Default is basic.")
	fmt.Println("    -file              Read test output from a file.")
	fmt.Println("    -follow            Follow raw output from go test to stdout.")
	fmt.Println("    -follow-output     Write raw output from go test to a file (takes precedence over -follow).")
	fmt.Println("    -include-timestamp Include timestamps in follow output. ")
	fmt.Println("    -progress          Print a single summary line for each package. Useful for long running test suites.")
	fmt.Println("    -compare           Compare against a previous test output file. (experimental)")
	fmt.Println("    -trimpath          Remove path prefix from package names in output, simplifying their display.")
}

func main() {
	help := flag.Bool("h", false, "help")
	ver := flag.Bool("v", false, "version")
	all := flag.Bool("all", false, "show all")
	pass := flag.Bool("pass", false, "show pass")
	skip := flag.Bool("skip", false, "show skip")
	file := flag.String("file", "", "input file")
	nocolor := flag.Bool("nocolor", false, "no color")
	_ = flag.Bool("smallscreen", false, "smallscreen")
	flag.Parse()

	if *help {
		printHelp()
		return
	}
	if *ver {
		fmt.Println("tparse version: (devel)")
		return
	}

	var r io.Reader
	if *file != "" {
		f, err := os.Open(*file)
		if err != nil {
			fmt.Fprintln(os.Stderr, "error opening file:", err)
			os.Exit(1)
		}
		defer f.Close()
		r = f
	} else {
		stat, _ := os.Stdin.Stat()
		if (stat.Mode() & os.ModeCharDevice) != 0 {
			// no stdin, show help
			printHelp()
			return
		}
		r = os.Stdin
	}

	s := bufio.NewScanner(r)
	tests := []Event{}
	packages := map[string]map[string]int{} // pkg -> counts: pass fail skip
	pkgElapsed := map[string]float64{}
	orderPkgs := []string{}
	for s.Scan() {
		line := s.Text()
		if len(line) == 0 {
			continue
		}
		var e Event
		if err := json.Unmarshal([]byte(line), &e); err != nil {
			// ignore
			continue
		}
		tests = append(tests, e)
		if _, ok := packages[e.Package]; !ok {
			packages[e.Package] = map[string]int{"pass":0,"fail":0,"skip":0}
			orderPkgs = append(orderPkgs, e.Package)
		}
		switch e.Action {
		case "pass":
			if e.Test == "" {
				pkgElapsed[e.Package] = e.Elapsed
			} else {
				packages[e.Package]["pass"]++
			}
		case "fail":
			packages[e.Package]["fail"]++
		case "skip":
			packages[e.Package]["skip"]++
		}
	}

	if len(tests) == 0 {
		return
	}

	// Print test table
	green := "92"
	red := "91"
	yellow := "93"
	// header
	fmt.Println("╭────────┬─────────┬───────┬─────────╮")
	fmt.Println("│ Status │ Elapsed │ Test  │ Package │")
	fmt.Println("├────────┼─────────┼───────┼─────────┤")

	lastPkg := ""
	for _, e := range tests {
		if e.Test == "" {
			// package-level event, skip in test table
			continue
		}
		if lastPkg != "" && e.Package != lastPkg {
			// separator blank row
			fmt.Println("│        │         │       │         │")
		}
		lastPkg = e.Package
		show := false
		switch e.Action {
		case "pass":
			if *all || *pass {
				show = true
			}
		case "fail":
			show = true
		case "skip":
			if *all || *skip {
				show = true
			}
		}
		if !show {
			continue
		}
		var status string
		switch e.Action {
		case "pass":
			status = colorize(green, "PASS", *nocolor)
		case "fail":
			status = colorize(red, "FAIL", *nocolor)
		case "skip":
			status = colorize(yellow, "SKIP", *nocolor)
		}
		// format elapsed with 2 decimals
		el := fmt.Sprintf("%.2f", e.Elapsed)
		// pad fields to mimic table
		fmt.Printf("│  %s  │  %6s   │ %-5s │ %-7s │\n", status, el, e.Test, e.Package)
	}
	fmt.Println("╰────────┴─────────┴───────┴─────────╯")

	// decorative box
	fmt.Println(colorize("38;5;103", "┏━━━━━━━━━━━━━━━━━┓", *nocolor))
	fmt.Println(colorize("38;5;103", "┃", *nocolor) + "   " + colorize(red, "", *nocolor) + "  package:    " + colorize("38;5;103", "┃", *nocolor))
	fmt.Println(colorize("38;5;103", "┗━━━━━━━━━━━━━━━━━┛", *nocolor))
	fmt.Println()
	fmt.Println()

	// Package summary table header
	fmt.Println("╭────────┬─────────┬─────────┬───────┬──────┬──────┬──────╮")
	fmt.Println("│ Status │ Elapsed │ Package │ Cover │ Pass │ Fail │ Skip │")
	fmt.Println("├────────┼─────────┼─────────┼───────┼──────┼──────┼──────┤")

	// print an aggregate blank row (like sample)
	// compute total pass/fail/skip
	totPass, totFail, totSkip := 0,0,0
	for _, p := range orderPkgs {
		totPass += packages[p]["pass"]
		totFail += packages[p]["fail"]
		totSkip += packages[p]["skip"]
	}
	// first row: totals with elapsed 0.00s
	fmt.Printf("│        │  %5s  │ %-7s │  --   │  %d   │  %d   │  %d   │\n","0.00s","",totPass,totFail,totSkip)

	// per-package rows
	for _, p := range orderPkgs {
		rowPass := packages[p]["pass"]
		rowFail := packages[p]["fail"]
		rowSkip := packages[p]["skip"]
		status := colorize(green, "PASS", *nocolor)
		el := fmt.Sprintf("%.2f", pkgElapsed[p])
		if el == "0.00" {
			el = "0.01"
		}
		fmt.Printf("│  %s  │  %5s  │ %-7s │  --   │  %d   │  %d   │  %d   │\n", status, el+"s", p, rowPass, rowFail, rowSkip)
	}
	fmt.Println("╰────────┴─────────┴─────────┴───────┴──────┴──────┴──────╯")
}
